 [InitializeOnLoad] public static class TestMountainV2Intake {
  const string ScenePath="Assets/Scenes/AlpsTerrainTest.unity",Source="Assets/Snowglow/Catalog/Sources/AlpsMountainsV2/",Log="Logs/AlpsMountainsV2/";
  [Serializable] class Export {public Item[] assets;public string sha256;}
  [Serializable] class Item {public string slug,label;public int triangles;public float[] size;}
  class Pose {public string name,id;public Vector3 at,scale;public Quaternion rotation;public float width;}
  static TestMountainV2Intake(){EditorApplication.update+=Pending;}
  static void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("V2 test mountains: "+why);}
  static void Pending(){const string marker="Logs/AlpsMountainsV2.request";if(!File.Exists(marker)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete(marker);Directory.CreateDirectory(Log);try{Apply();}catch(Exception e){File.WriteAllText(Log+"Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Vector3[] Vertices(MeshFilter f){using(var data=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh))using(var a=new NativeArray<Vector3>(data[0].vertexCount,Allocator.Temp)){data[0].GetVertices(a);return a.ToArray();}}
  static Bounds Bounds(GameObject g){var renderers=g.GetComponentsInChildren<MeshRenderer>();Check(renderers.Length>0,"rendered model");var b=renderers[0].bounds;foreach(var r in renderers.Skip(1))b.Encapsulate(r.bounds);return b;}
  static float Ground(MeshCollider terrain,Vector3 p){var b=terrain.bounds;Check(p.x>=b.min.x&&p.x<=b.max.x&&p.z>=b.min.z&&p.z<=b.max.z,"base within terrain "+p);Check(terrain.Raycast(new Ray(new Vector3(p.x,b.max.y+20,p.z),Vector3.down),out var hit,2000),"terrain support "+p);return hit.point.y;}
  public static void Apply(){
   Directory.CreateDirectory(Log);var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"operate on current test scene only");var group=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement").transform;Check(group.childCount==8&&group.Cast<Transform>().All(t=>t.GetComponent<CatalogPlacement>().assetId.StartsWith("alps-rebuild-mountain_")),"eight original placements; refuse repeat");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");string backup=Log+"InMemory-before-"+stamp+".unity";Check(EditorSceneManager.SaveScene(scene,backup,true),"preserve current user edits");File.Copy(ScenePath,Log+"Disk-before-"+stamp+".unity");var poses=group.Cast<Transform>().Select(t=>new Pose{name=t.name,id=t.GetComponent<CatalogPlacement>().assetId,at=t.position,rotation=t.rotation,scale=t.localScale,width=Mathf.Max(Bounds(t.gameObject).size.x,Bounds(t.gameObject).size.z)}).ToArray();var old=group.Cast<Transform>().ToArray();var terrain=scene.GetRootGameObjects().Single(g=>g.name=="Revised attached terrain | 1:1 metres").GetComponentInChildren<MeshCollider>();var terrainMesh=terrain.sharedMesh;var camera=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).Single();var report=new List<string>();
   try{
    var export=JsonUtility.FromJson<Export>(File.ReadAllText(Source+"ExportMetrics.json"));Check(export.assets.Length==8,"eight supplied variants");string palette=Source+"IcyPalette.png";if(!File.Exists(palette))File.Copy("Assets/Snowglow/Levels/AlpsTerrainTest/MountainSeating/IcyMountainPalette.png",palette);AssetDatabase.ImportAsset(palette,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(palette);ti.filterMode=FilterMode.Point;ti.wrapMode=TextureWrapMode.Clamp;ti.mipmapEnabled=false;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>(Source+"IcyMountains.mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name="Supplied V2 mountains | current icy palette",enableInstancing=true};mat.SetColor("_BaseColor",Color.white);mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(palette));mat.SetFloat("_Smoothness",0);mat.SetColor("_SpecColor",Color.black);AssetDatabase.CreateAsset(mat,Source+"IcyMountains.mat");}
    var entries=new Dictionary<string,CatalogAsset>();foreach(var row in export.assets){string id="alps-mountains-v2-"+row.slug.ToLowerInvariant();var entry=CatalogPreparation.Library().Find(id);if(!entry){string path=Source+row.slug+".fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.isReadable=false;importer.globalScale=1;importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"AlpsV2Palette"),mat);importer.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);Check((Bounds(model).size-new Vector3(row.size[0],row.size[1],row.size[2])).magnitude<.2f,"metre basis "+row.slug);var draft=CatalogPreparation.Draft("V2 "+row.label,CatalogKind.Landscape,AssetSource.ImportedModel,null,"User supplied Snow_District_Alps_Mountains(2).blend; checksum "+export.sha256+". Embedded texts not executed. Evaluated source geometry retained, current icy palette derivative.");draft.id=id;draft.creationSourcePath="SourceAssets/AlpsMountainsV2/Mountains.blend";entry=CatalogPreparation.Prepare(model,CatalogKind.Landscape,"V2 "+row.label,1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft,true);var prefab=PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(entry.prefab));try{var original=AlpsRebuildAssets.Find(row.slug).prefab;prefab.transform.Find("VisualRoot").localRotation=original.transform.Find("VisualRoot").localRotation;foreach(var r in prefab.GetComponentsInChildren<MeshRenderer>())r.sharedMaterial=mat;foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;f.gameObject.isStatic=true;}PrefabUtility.SaveAsPrefabAsset(prefab,AssetDatabase.GetAssetPath(entry.prefab));}finally{PrefabUtility.UnloadPrefabContents(prefab);}entry.tags=new[]{"alps","mountains-v2","low-poly","test-scene"};entry.assumptions="Supplied geometry, original proportions and UVs; shared icy palette; static nonconvex matching mesh collision. Scene fitting is uniform footprint scale plus Y translation only. NeedsReview; no device acceptance.";CatalogPreparation.RecordMetrics(entry);EditorUtility.SetDirty(entry);}Check(entry.triangles==row.triangles,"source triangle count "+row.slug);entries.Add(row.slug.ToLowerInvariant(),entry);}
    var used=new HashSet<string>();for(int i=0;i<poses.Length;i++){var pose=poses[i];string slug=pose.id.Substring("alps-rebuild-".Length);if(!used.Add(slug)){slug="mountain_08";Check(used.Add(slug),"all eight variants used");}var entry=entries[slug];var g=(GameObject)PrefabUtility.InstantiatePrefab(entry.prefab,scene);g.transform.SetParent(group,false);g.name=pose.name.Split('|')[0].Trim()+" | supplied V2 "+slug;g.GetComponent<CatalogPlacement>().placementId="test-mountains-v2-"+i;g.transform.SetPositionAndRotation(new Vector3(pose.at.x,0,pose.at.z),pose.rotation);var b=Bounds(g);float scale=pose.width/Mathf.Max(b.size.x,b.size.z);g.transform.localScale=Vector3.one*scale;var footprint=Bounds(g);var edge=terrain.bounds;float fit=1;fit=Mathf.Min(fit,(edge.max.x-.5f-pose.at.x)/(footprint.max.x-pose.at.x),(pose.at.x-edge.min.x-.5f)/(pose.at.x-footprint.min.x),(edge.max.z-.5f-pose.at.z)/(footprint.max.z-pose.at.z),(pose.at.z-edge.min.z-.5f)/(pose.at.z-footprint.min.z));Check(fit>.5f,"replacement fits existing slot");scale*=fit;g.transform.localScale=Vector3.one*scale;var f=g.GetComponentsInChildren<MeshFilter>().Single();var local=Vertices(f).Select(v=>g.transform.InverseTransformPoint(f.transform.TransformPoint(v))).ToArray();float bottom=local.Min(v=>v.y);var ring=local.Where(v=>v.y<=bottom+.05f).Distinct().OrderBy(v=>Mathf.Atan2(v.z,v.x)).ToArray();Check(ring.Length>=12,"supplied bottom rim "+slug);var samples=new List<Vector3>();for(int j=0;j<ring.Length;j++){var x=g.transform.TransformPoint(ring[j]);var y=g.transform.TransformPoint(ring[(j+1)%ring.Length]);int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(x,y)/2));for(int k=0;k<n;k++)samples.Add(Vector3.Lerp(x,y,k/(float)n));}float dy=samples.Min(p=>Ground(terrain,p)-p.y-.5f);g.transform.position+=Vector3.up*dy;foreach(var sample in samples)Check(sample.y+dy<=Ground(terrain,sample)-.49f,"buried source base");float visible=Vertices(f).Max(v=>{var w=f.transform.TransformPoint(v);return w.y-Ground(terrain,w);});Check(visible>10,"visible source peak");Check(Mathf.Abs(Mathf.Max(Bounds(g).size.x,Bounds(g).size.z)-pose.width*fit)<.05f,"existing footprint or boundary-limited uniform fit retained");Check(g.transform.position.x==pose.at.x&&g.transform.position.z==pose.at.z&&g.transform.rotation==pose.rotation,"user XZ/yaw retained");report.Add(g.name+" | XZ="+pose.at.x+","+pose.at.z+" | boundary fit="+fit+" | scale="+scale+" | baseY="+dy+" | visible="+visible+"m | triangles="+entry.triangles);}
    foreach(var t in old)UnityEngine.Object.DestroyImmediate(t.gameObject);Check(group.childCount==8&&used.Count==8,"eight unique replacements");Physics.SyncTransforms();AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene,ScenePath),"save replacements");scene=EditorSceneManager.OpenScene(ScenePath);var saved=scene.GetRootGameObjects().Single(g=>g.name=="Mountains | provisional placement");Check(saved.GetComponentsInChildren<MeshCollider>().Length==8&&saved.GetComponentsInChildren<MeshFilter>().All(f=>f.GetComponent<MeshCollider>().sharedMesh==f.sharedMesh),"saved matching collision");Check(scene.GetRootGameObjects().Single(g=>g.name=="Revised attached terrain | 1:1 metres").GetComponentInChildren<MeshCollider>().sharedMesh==terrainMesh,"terrain unchanged");Capture(scene,Log+"Overview.png",new Vector3(1150,850,0),Vector3.zero);int index=0;foreach(Transform t in saved.transform){var b=Bounds(t.gameObject);Capture(scene,Log+"Mountain"+(++index).ToString("D2")+".png",b.center+new Vector3(1,.5f,-1).normalized*Mathf.Max(b.size.x,b.size.z)*1.4f,b.center);}File.WriteAllText(Log+"Validation.txt","PASS: eight supplied V2 mountain variants prepared and saved/reopened in AlpsTerrainTest only. All eight used once; duplicate old cliff slot uses supplied broad massif. User XZ/rotation retained; footprint widths matched with uniform reduction only where needed to keep new shape within terrain; Y translation seats source bottom rim .5m under actual terrain. Unmodified source meshes/UVs; current icy palette retained. Static shared mesh colliders match visible geometry. Total11819 triangles. Existing terrain/game scenes/profile preserved separately. Native overview/eight individual views produced. No Play/device acceptance.\n"+string.Join("\n",report));
   }catch{if(SceneManager.GetActiveScene().isDirty)EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Log+"Failed-unsaved-"+stamp+".unity",true);File.Copy(backup,ScenePath,true);AssetDatabase.ImportAsset(ScenePath,ImportAssetOptions.ForceUpdate);EditorSceneManager.OpenScene(ScenePath);throw;}
  }
  static void Capture(Scene scene,string path,Vector3 position,Vector3 target){var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>()).Single();var go=new GameObject("Temporary V2 mountain audit camera");SceneManager.MoveGameObjectToScene(go,scene);var camera=go.AddComponent<Camera>();camera.CopyFrom(original);camera.enabled=false;camera.orthographic=false;camera.fieldOfView=55;camera.aspect=4f/3;camera.layerCullDistances=new float[32];camera.farClipPlane=3000;camera.transform.SetPositionAndRotation(position,Quaternion.LookRotation(target-position));var rt=RenderTexture.GetTemporary(1200,900,24);var old=RenderTexture.active;var image=new Texture2D(1200,900,TextureFormat.RGB24,false);try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(go);}}
 }
